!INC Local Scripts.ChartAutomation

function ChartInfo()
{
 	this.m_nTransparency = 60;
	this.m_bShowDataMarkers = false;
	this.m_nMarkerSize = 0;
	this.m_nMarkerShape = 0;
	this.m_bShowDataLabels = false;
	this.m_nDataLabelAngle = 2;
	this.m_chartCategory=11; // Area
	this.m_chartType=1; // BCGP_CT_SIMPLE
	this.m_chartCurveType=2; // SPLINE
	//this.m_chartCategory = ChartCategory.chartArea;
	//this,m_chartType = ChartType.chartTypeRANGE;
	//this.m_chartCurveType = ChartCurveType.chartCurveTypeSPLINE;
}

function ChartData( a, b, c, d)
{
	this.name = a;
	this.y=b;
	this.y1=c;
	this.series=d;
}

function Rand(min, max) {
  min = cephes.ceil(min);
  max = cephes.floor(max);
  return cephes.floor(cephes.drand() * (max - min)) + min; //The maximum is exclusive and the minimum is inclusive
}


function ConstructChart( chartGuid  )
{
	var chartInfo = new ChartInfo();

	//var element as EA.Element;
	var chart as EA.Chart;
	var series1 as EA.ChartSeries;
	var series2 as EA.ChartSeries;
	var series3 as EA.ChartSeries;
	var chartElement  as EA.Element;
	chartElement = GetElementByGuid( chartGuid );
	if(chartElement)
	{
		chart = chartElement.GetChart();
		chart.Title = "Temperature Ranges by Month/Year:";
		chart.SetChartType(chartInfo.m_chartCategory, chartInfo.m_chartType, false, true);
		chart.SetCurveType(chartInfo.m_chartCurveType);

		series1 = chart.CreateSeries("2020");
		series2 = chart.CreateSeries("2019");
		series3 = chart.CreateSeries("2018");

		var arMonths = [ "jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec" ];
		var arData= [5., 12., 19, 22, 19, 24, 22, 24, 18, 14, 10, 7 ];
		for (var m = 0; m < 12; m++)
		{
			var data1 = new ChartData( arMonths[m], arData[m],  Rand(2,5), 0);
			var data2 = new ChartData( arMonths[m], arData[m]+ Rand(-5,10),  Rand(2,5), 1);
			var data3 = new ChartData( arMonths[m], arData[m]+ Rand(-5,10),  Rand(2,5), 2);
			chart.AddChartDataYY1( data1.name, data1.y, data1.y1, data1.series);
			chart.AddChartDataYY1( data2.name, data2.y, data2.y1, data2.series);
			chart.AddChartDataYY1( data3.name, data3.y, data3.y1, data3.series);
		}
		var dblDataLabelAngle = (chartInfo.m_nDataLabelAngle - 2) * 45;
		chart.ShowDataMarkers( chartInfo.m_bShowDataMarkers, Math.max(7, 5 * (chartInfo.m_nMarkerSize + 1)), chartInfo.m_nMarkerShape);
		chart.ShowDataLabels( chartInfo.m_bShowDataLabels, true, true, dblDataLabelAngle);
		chart.SetThemeOpacity(100 - chartInfo.m_nTransparency);
		chart.Redraw();
	}
}

