!INC Local Scripts.ChartAutomation

function Rand(min, max) {
    return Math.random() * (max - min) + min;
}
function BoxPlotData()
{
	this.IsEmpty=true;
	this.Average=1.0;
	this.MinV=0.0;
	this.MaxV=0.0;
	this.Q1=0.0;
	this.Q2=0.0;
	this.Q3=0.0;
	this.Notch=0.0;
}

function roundForTolerance(val, tolerance)
{
    if( val - (val - tolerance) >= tolerance)
		return val + tolerance;
	return val - tolerance;
}

function BoxPlotCompare(arg1, arg2)
{
	var nRes=0;
	if (arg1 < arg2)	{
		nRes = -1;
	}
	else if (arg2 < arg1)	{
		nRes = 1;
	}
	return nRes;
}

function BoxPlotQuartile( arData, type)
{
	// type:
	// 0 - minimum
	// 1 - Q1
	// 2 - Q3 (median)
	// 3 - Q2
	// 4 - maximum
	var nCount = arData.length;
    if (nCount == 1) 
        return arData[0];

    var nIndex1 = 0;
    var nIndex2 = 0;

    if (type == 0 || type == 4)    {
        nIndex1 = type == 0 ? 0 : nCount - 1;
        nIndex2 = nIndex1;
    }
    else
    {
        var bOddSize = (nCount % 2) != 0;
        if (type == 2)
        {
            nIndex1 = nCount / 2;
            nIndex2 = nIndex1;
            if (!bOddSize)
            {
                nIndex2--;
            }
        }
        else
        {
            var nCount2 = nCount / 2;
            nIndex1 = nCount2 / 2;
            if (type == 3)
            {
                nIndex1 += nCount2;
                if (bOddSize)
                      nIndex1 += 1;
            }
            nIndex2 = nIndex1;
            if ((nCount2 % 2) == 0)
            {
                nIndex2 -= 1;
            }
        }
    }
    var result = arData[nIndex1];
    if (nIndex1 != nIndex2)
    {
        result = (arData[nIndex2] + result) / 2.0;
    }
    return result;
}


function BoxPlotCalculate( series, arData)
{
	var data = new BoxPlotData();
	// calc average
	var nCount = arData.length;
	var iAve = 0;
	for (var i = 0; i < nCount; i++)
		iAve += arData[i];

	data.Average = parseFloat(( iAve / nCount).toFixed(4));

	// sort
	arData.sort(BoxPlotCompare);

	// calculate min max and quartiles
	data.MinV = BoxPlotQuartile(arData, 0);
	data.Q1 = BoxPlotQuartile(arData, 1);
	data.Q2 = BoxPlotQuartile(arData, 2);
	data.Q3 = BoxPlotQuartile(arData, 3);
	data.MaxV = BoxPlotQuartile(arData, 4);
	data.Notch = 1.58 * cephes.fabs((data.Q3 - data.Q1)) / cephes.sqrt(nCount);

	Session.Output( "ave:" + data.Average + ", min:" + data.MinV + ", q1:" + data.Q1 + ", q2:" +  data.Q2 + ", q3:" +  data.Q3 + ", max:" +  data.MaxV + ", n:" +  data.Notch );
	series.AddBoxPlotData( data.Average, data.MinV, data.Q1, data.Q2, data.Q3, data.MaxV, data.Notch);

}

function ConstructChart( guid )
{
	var chart as EA.Chart;
	var series as EA.ChartSeries;
	var series1 as EA.ChartSeries;
	var series2 as EA.ChartSeries;
	var series3 as EA.ChartSeries;
	var element as EA.Element;
	var nPoints = 12;
	var nData = 16;
	var dblMin = 0.0;
	var dblMin = 0.0;
	var nSeries=3;
	var arData = new Array(nData);

	element = GetElementByGuid(guid);
	if(element)
	{
		chart = element.GetChart();
		chart.Title = "Site visitors";
		chart.SetChartType( ChartCategory.BoxPlot(), ChartType.SIMPLE(), false, true);
		chart.SetThemeOpacity(30);

		series1 = chart.CreateSeries("Europe");
		series2 = chart.CreateSeries("Asia");
		series3 = chart.CreateSeries("Oceania");

		nSeries = chart.GetSeriesCount();
		for (var i = 0; i < nSeries; i++)
		{
			series = chart.GetSeries(i);
			for (var j = 0; j < nPoints; j++)
			{
				dblMin = Rand(0.0, 1000.0);
				dblMax = Rand(5000.0, 10000.0 - dblMin);
				for (var k = 0; k < nData; k++)
				{
					arData[k] = roundForTolerance(Rand(dblMin, dblMax), 0.5);
				}
				BoxPlotCalculate(series,arData);
			}
		}
	}
	chart.Redraw();
}

!INC Local Scripts.ChartAutomation

function ConstructChart( chartGuid )
{
	var chart as EA.Chart;
	var series1 as EA.ChartSeries;
	var series2 as EA.ChartSeries;
	var series3 as EA.ChartSeries;
	var chartElement  as EA.Element;
	chartElement = GetElementByGuid( chartGuid );
	if(chartElement)
	{
		chart = chartElement.GetChart();
		chart.Title = "Area, Column and Line:";

		series1 = chart.CreateSeriesEx( "Area", ChartColor.Default(), ChartType.DEFAULT(), ChartCategory.Area());
		series2 = chart.CreateSeriesEx( "Column", ChartColor.Default(), ChartType.DEFAULT(), ChartCategory.Column());
		series3 = chart.CreateSeriesEx( "Line", ChartColor.Default(), ChartType.DEFAULT(), ChartCategory.Line());
		chart.SetThemeOpacity(70);

		var plotData = [
			[ 5., 6., 7., 14., 19., 21., 26., 27., 28., 31., 33., 38.0 ],
			[ 5., 12., 19, 20, 15, 12, 14, 23, 18, 14, 10, 7 ],
			[ 35., 32., 29, 26, 25, 24, 21, 19, 12, 8, 6, 0 ]
		];
		var columns = [ "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec" ];

		for (var nMonth = 0; nMonth < 12; nMonth++)
		{
			series1.AddDataPoint3(columns[nMonth], plotData[0][nMonth]);
			series2.AddDataPoint(plotData[1][nMonth]);
			series3.AddDataPoint(plotData[2][nMonth]);
		}
		var style = series3.GetSeriesFormat();
		style.SetCurveType(ChartCurveType.SPLINE_HERMITE());
		style.SetSeriesLineWidth(3);
		chart.Redraw();
	}
}

