!INC Local Scripts.ChartAutomation

function ConstructChart( chartGuid )
{
	var chart as EA.Chart;
	var series1 as EA.ChartSeries;
	var series2 as EA.ChartSeries;
	var series as EA.ChartSeries;
	var axisX as EA.ChartAxis;
	var axisY as EA.ChartAxis;

	var chartElement  as EA.Element;
	chartElement = GetElementByGuid( chartGuid );
	if(chartElement)
	{
		chart = chartElement.GetChart();
		chart.ShowAxisIntervalInterlacing(ChartAxisType.X_PRIMARY_AXIS());
		chart.SetChartType(ChartCategory.Polar(), ChartType.SIMPLE(), false, true);

		series1 = chart.CreateSeries("Series 1");
		series2 = chart.CreateSeries("Series 2");

		series1.AddDataPoint(120., 0.);
		series1.AddDataPoint(110., 30.);
		series1.AddDataPoint(180., 60.);
		series1.AddDataPoint(145, 90.);
		series1.AddDataPoint(145, 120.);
		series1.AddDataPoint(100, 180.);
		series1.AddDataPoint(190, 225.);
		series1.AddDataPoint(120, 270.);
		series1.AddDataPoint(130, 300.);

		series2.AddDataPoint(220., 0.);
		series2.AddDataPoint(80., 30.);
		series2.AddDataPoint(100., 60.);
		series2.AddDataPoint(70, 90.);
		series2.AddDataPoint(20, 120.);
		series2.AddDataPoint(200, 150.);
		series2.AddDataPoint(210, 180.);
		series2.AddDataPoint(110, 210.);
		series2.AddDataPoint(150, 270.);
		series2.AddDataPoint(170, 300.);
		series2.AddDataPoint(120, 330.);

		axisX = chart.GetChartAxis( ChartAxisType.X_POLAR_AXIS());
		axisY = chart.GetChartAxis( ChartAxisType.Y_POLAR_AXIS());
		axisX.SetTickMark( ChartAxisTickMarkType.CROSS());
		axisY.SetTickMark( ChartAxisTickMarkType.CROSS());

		chart.SetThemeOpacity(30);

		for (var i = 0; i < chart.GetSeriesCount(); i++)
		{
			series = chart.GetSeries(i);
			var style = series.GetSeriesFormat();
			style.SetCurveType(ChartCurveType.SPLINE());
			style.SetSeriesOutlineDashStyle(ChartDashStyle.SOLID());
			style.SetSeriesLineWidth(2);
			if(i==0)
			{
				series.CloseShape(true,true);
			}
		}
		chart.Redraw();
	}
}

