!INC Local Scripts.ChartAutomation

function Range()
{
	this.start = new Date();
	this.end = this.start; 
	this.interval = 5;

	this.getElapsed = function()
	{
		this.end.setTime( this.start.getTime() + ( this.interval * 60000) );
		//Session.Output( "time is " + this.end.toString());
		return this.end.getTime();
	}
}

function Rand( incMin, incMax) 
{
	var minVal = Math.min(incMin, incMax);
	var maxVal = Math.max(incMin, incMax);
	return (maxVal - minVal) * Math.random();
}

