function ConstructChart( chartGuid )
{
	var chart as EA.Chart;
	var series1 as EA.ChartSeries;
	var series2 as EA.ChartSeries;
	var axisX as EA.ChartAxis;
	var axisY as EA.ChartAxis;
	var dpv as EA.ChartDataValue;

	var chartElement  as EA.Element;
	chartElement = GetElementByGuid( chartGuid );
	if(chartElement)
	{
		chart = chartElement.GetChart();
		chart.Title = "Stocks";

		series1 = chart.CreateSeriesEx( "CUR1/CUR2", ChartColor.Default(), ChartType.DEFAULT(), ChartCategory.Stock());
		axisX = chart.GetChartAxis( ChartAxisType.X_PRIMARY_AXIS());
		axisY = chart.GetChartAxis( ChartAxisType.Y_PRIMARY_AXIS());

		axisX.SetAxisName( "Date/Time",true);
		axisX.SetDataFormat("%H:%M",true);
		axisX.EnableMajorUnitIntervalInterlacing(false);

		axisY.SetAxisName( "CUR1/CUR2",true);
		axisY.SetDataFormat("%.4f",false);

		series1.SetStockSeriesType(ChartStockSeriesType.LineOpen());

		LoadStockData(series1);

		// generate sample data for volumes
		series2 = chart.CreateSeriesEx( "Volume", ChartColor.Default(), ChartType.DEFAULT(), ChartCategory.Histogram());
		for (var i = 0; i < series1.GetDataPointCount(); i++)
		{
			dpv = series1.GetDataPointValue(i, ChartDataIndex.X());
			var y = Rand(700000, 90000000);
			var x = dpv.GetValue();
			series2.AddDataPoint2( y, x);
		}

		// setup secondary main Y axis
		chart.ShowAxis(ChartAxisType.Y_SECONDARY_AXIS(), true, true);
		axisY2 = chart.GetChartAxis(ChartAxisType.Y_SECONDARY_AXIS());
		axisY2.SetAxisName( "CUR1/CUR2",true);

		// Setup custom axis for volumes:
		axisVol = axisY.Split(60, 6, false,0);
		axisVol.SetDisplayUnits(1000000); // displays volume in millions
		axisVol.SetDataFormat("%.fM",false); // ... with postfix M
		axisVol.SetCrossType(ChartAxisCrossType.MAXIMUM_AXIS_VALUE()); // at right side
		axisVol.SetTickMark( ChartAxisTickMarkType.INSIDE()); // in this case "inside" points tick marks outside
		axisVol.SetAxisName( "Volume Axis",true);

		series2.SetRelatedAxis( axisVol.GetGuid(), ChartAxisIndex.Y());

		chart.Redraw();
	}
}

!INC Local Scripts.ChartAutomation

var bShowWalls = false;
var bShowFloor = false;

function ConstructChart( chartGuid )
{
	var chart as EA.Chart;
	var series as EA.ChartSeries;
	var diagram as EA.ChartDiagram3D;
	var element = GetElementByGuid(chartGuid);
	chart = element.GetChart();
	diagram3D = chart.GetDiagram3D();

	chart.ShowAxisIntervalInterlacing(ChartAxisType.X_PRIMARY_AXIS());
	chart.SetChartType(ChartCategory.Surface3D(), ChartType.SIMPLE(), false, false);

	series = chart.CreateSeries("Surface");

	var dblStep = 0.15;
	var dblMinRange = -3;
	var dblMaxRange = 3.;

	for (var z = dblMinRange; z <= dblMaxRange + Number.EPSILON; z += dblStep)
	{
		for (var x = dblMinRange; x <= dblMaxRange + Number.EPSILON; x += dblStep)
		{
			var y = (cephes.cos(z * z) * z - cephes.sin(x * x) * x);	
			chart.AddChartDataYXZ( y, x, z, 0);
		}
	}

	// calculate levels using minimum and maximum series values
	series.SetLevelRangeMode(ChartLevelRangeMode.MINMAX_SERIES());

	series.AddSurfaceColours( [ ChartColor.LightPink(),  ChartColor.LightSteelBlue(), ChartColor.DarkSlateGray(), ChartColor.LightSlateGray() ] );

	// set up axes
	var axisX = chart.GetChartAxis(ChartAxisType.X_PRIMARY_AXIS());
	var axisZ = chart.GetChartAxis(ChartAxisType.Z_PRIMARY_AXIS());

	// center the chart by X and Z
	axisX.SetFixedDisplayRange(dblMinRange - 0.5, dblMaxRange + 0.5);
	axisZ.SetFixedDisplayRange(dblMinRange - 0.5, dblMaxRange + 0.5);

	// turn off X and Z major grid lines
	axisX.ShowMajorGridLines(false);
	axisZ.ShowMajorGridLines(false);

	// no interval interlacing on X axis
	axisX.EnableMajorUnitIntervalInterlacing(false);

	diagram3D.SetRenderingType(RenderingType.SOFTWARE());

	for (i = 0; i < chart.GetSeriesCount(); i++)
	{
		series = chart.GetSeries(i);
		series.SetFrameStyle(ChartFrameStyle.MESH());
		series.SetWireFrame(false);
		series.SetColorMapCount(16);
		series.SetColorMode(ChartColorMode.MULTIPLE());
		series.SetSurfaceType(ChartSurfaceType.LEVELS());
		series.SetFrameColor(ChartColor.Default());
		series.SetDrawFlat(false);
	}
	// Draw walls and floor:
	var dwoFlags = 0;
	if (bShowWalls)
		dwoFlags |= ChartDrawWallOptions.DRAW_ALL_WALLS();
	if (bShowFloor)
		dwoFlags |= ChartDrawWallOptions.DRAW_FLOOR() ;
	else
		dwoFlags |= ChartDrawWallOptions.OUTLINE_FLOOR();
	diagram3D.SetDrawWallOptions(	 dwoFlags, false );

	// Show vertical axis:
	var axisY = chart.GetChartAxis(ChartAxisType.Y_PRIMARY_AXIS());
	axisY.Visible=true;

	chart.Redraw();
}

